{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "The closest structural analog, verapamil, has an absolute oral bioavailability of 27% in healthy volunteers, at or above the 20% threshold, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "The R-enantiomer of verapamil, equally similar to the query, shows about 50% absolute oral bioavailability, demonstrating that the verapamil scaffold can achieve well above 20% F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Gallopamil, a close verapamil analog with an additional methoxy group, has about 96% oral bioavailability, indicating that central-region modifications can yield high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Norverapamil, the N-desmethyl verapamil analog, has 49% oral bioavailability, supporting high F for this dimethoxyphenethylamine series.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "The S-enantiomer of verapamil has lower F (~10.5%), but this is stereoselective and the query is achiral, so it is a weaker contradictory signal.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C34"],
      "claim": "Terameprocol, a dimethoxyphenyl compound without the basic amine, has ~2% F, but poor transferability due to lack of the ionizable amine and different scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest verapamil analogs cluster around or above 20% oral bioavailability, with several related dimethoxyphenethylamine drugs showing high F; the main low-F evidence is stereoselective or structurally less transferable, so the query is predicted high.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the cyclic disulfone modification in the query.",
    "Unknown effect of the two sulfonyl groups on membrane permeability and first-pass metabolism relative to verapamil.",
    "No human pharmacokinetic data for the exact query molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

